input = sys.stdin.read
MOD = 10**9 + 7

def is_prime(num):
    if num <= 1:
        return False
    if num <= 3:
        return True
    if num % 2 == 0 or num % 3 == 0:
        return False
    i = 5
    while i * i <= num:
        if num % i == 0 or num % (i + 2) == 0:
            return False
        i += 6
    return True

def solve():
    data = input().split()
    t = int(data[0])
    cases = [int(data[i]) for i in range(1, t+1)]

    max_n = max(cases)
    dp = [0] * (max_n + 1)

    if max_n >= 3:
        dp[3] = 4

    if max_n >= 5:
        dp[5] = 12

    for i in range(6, max_n + 1):
        dp[i] = (dp[i-2] * 2) % MOD

    results = []
    for n in cases:
        results.append(dp[n])

    sys.stdout.write("\n".join(map(str, results)) + "\n")

solve()

